import{_ as s}from"./chunks/rayrai_pbr_texture_maps.CoEV03PI.js";import{_ as i,o as t,c as l,a5 as a,j as e,a as o}from"./chunks/framework.DrDMl0tG.js";const n="/assets/changelog_rayrai_showcase.1Mb9S-EB.mp4",d="/assets/changelog_deformable_objects.Bds-89By.mp4",c="/assets/changelog_granular_media.B8ekihya.mp4",y=JSON.parse('{"title":"Changelog: v2.2.0","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.2.0.md","filePath":"sections/changelog/v2.2.0.md"}'),p={name:"sections/changelog/v2.2.0.md"};function m(u,r,h,b,g,f){return t(),l("div",null,[...r[0]||(r[0]=[a('<h1 id="changelog-v2-2-0" tabindex="-1">Changelog: v2.2.0 <a class="header-anchor" href="#changelog-v2-2-0" aria-label="Permalink to &quot;Changelog: v2.2.0&quot;">​</a></h1><div class="release-banner"><div class="release-banner__eyebrow">Recent development notes</div><div class="release-banner__title">Rayrai, deformable objects, and granular media</div><div class="release-banner__text">Highlights for users upgrading to this release.</div></div><p>The latest changes are not just maintenance. They add three visible capabilities that affect how users inspect, build, and demonstrate simulations: the rayrai renderer, native deformable objects, and native granular media. The examples below were run from the package examples build and captured through rayrai for this changelog.</p><h2 id="rayrai-becomes-the-main-visual-workflow" tabindex="-1">Rayrai becomes the main visual workflow <a class="header-anchor" href="#rayrai-becomes-the-main-visual-workflow" aria-label="Permalink to &quot;Rayrai becomes the main visual workflow&quot;">​</a></h2>',4),e("p",null,[e("video",{class:"doc-video",src:n,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"rayrai complete showcase with RGB, depth, LiDAR, raw buffers, and scene visuals"})],-1),e("p",null,[e("img",{src:s,alt:"rayrai PBR texture maps example with textured material rendering"})],-1),e("p",null,"rayrai is now the supported in-process visualization path. For users, this means examples can render directly inside the simulation process, expose RGB/depth sensor buffers, preview LiDAR and point clouds, and show richer scenes without starting a separate legacy visualizer stack.",-1),e("p",null,"This release adds and restores rayrai example documentation, source files, and assets. They also bundle PBR material examples so users can immediately inspect real textured models with renderer-side material support.",-1),e("p",null,"User impact:",-1),e("ul",null,[e("li",null,"Run modern visualization examples directly from the installed package or examples build."),e("li",null,"Inspect RGB/depth camera output and raw sensor buffers through rayrai."),e("li",null,"Use bundled PBR assets instead of assembling renderer demo resources by hand.")],-1),e("h2",{id:"deformable-objects-are-now-example-ready",tabindex:"-1"},[o("Deformable objects are now example-ready "),e("a",{class:"header-anchor",href:"#deformable-objects-are-now-example-ready","aria-label":'Permalink to "Deformable objects are now example-ready"'},"​")],-1),e("p",null,[e("video",{class:"doc-video",src:d,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"deformable cloth and deformable cube stack in the rayrai TCP viewer"})],-1),a('<p>The deformable object example shows two workflows users can build on: an explicit cloth grid draping over a rigid obstacle and a stack of mesh-based deformable cubes. This makes the new deformable-body API concrete instead of leaving it as a header-level feature.</p><p>The example demonstrates particle counts, triangle topology, material tuning, mesh construction, and server streaming of dynamic deformable topology. Users can start from this scene when building cloth, soft shells, or deformable collision experiments.</p><p>User impact:</p><ul><li>Create cloth from explicit vertices and triangles.</li><li>Build deformable objects from closed OBJ meshes.</li><li>Stream deformable topology and vertex updates through <code>RaisimServer</code> and view them in rayrai.</li></ul><h2 id="granular-media-gets-a-native-robot-example" tabindex="-1">Granular media gets a native robot example <a class="header-anchor" href="#granular-media-gets-a-native-robot-example" aria-label="Permalink to &quot;Granular media gets a native robot example&quot;">​</a></h2>',5),e("p",null,[e("video",{class:"doc-video",src:c,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"ANYmal standing on native granular particles in the rayrai TCP viewer"})],-1),a('<p>Granular media is now visible as a native RaiSim feature through an ANYmal example standing on a particle bed. The scene shows the part users care about: rigid and articulated bodies interacting with granular particles while the particles are rendered as instanced visuals in rayrai.</p><p>The example exposes practical controls for particle resolution, layers, radius, spacing, stiffness, damping, friction, rolling friction, and substeps. It also prints contact and stability statistics after headless runs, so users can tune material behavior and check whether a configuration stayed stable.</p><p>User impact:</p><ul><li>Create granular beds with fixed and dynamic particles.</li><li>Couple granular particles to an articulated robot.</li><li>Visualize particle motion and tune material parameters from a runnable example.</li></ul><h2 id="build-upgrade-and-python-polish" tabindex="-1">Build, upgrade, and Python polish <a class="header-anchor" href="#build-upgrade-and-python-polish" aria-label="Permalink to &quot;Build, upgrade, and Python polish&quot;">​</a></h2><p>This release also improves the less visible surfaces that affect daily use. Upgrade scripts were added for Linux and Windows, automatic upgrade support was wired into CMake, Windows build configuration was adjusted, and RaiSimPy symbol exposure was fixed.</p><p>User impact:</p><ul><li>Easier package upgrades on Linux and Windows.</li><li>Fewer platform-specific CMake surprises.</li><li>Cleaner Python binding behavior for articulated systems and sensors.</li></ul>',8)])])}const w=i(p,[["render",m]]);export{y as __pageData,w as default};
